import{_ as a,o,c as i,a3 as l}from"./chunks/framework.DACwFHq9.js";const m=JSON.parse('{"title":"移动端 UI 开发指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/mobile-ui-development.md","filePath":"guide/mobile-ui-development.md","lastUpdated":1784790670000}'),t={name:"guide/mobile-ui-development.md"};function s(c,e,n,d,r,p){return o(),i("div",null,[...e[0]||(e[0]=[l(`<h1 id="移动端-ui-开发指南" tabindex="-1">移动端 UI 开发指南 <a class="header-anchor" href="#移动端-ui-开发指南" aria-label="Permalink to &quot;移动端 UI 开发指南&quot;">​</a></h1><p>本文是移动端新增和修改 UI 的当前规范。设计语言的完整决议、迁移理由与修订记录见 <a href="./mobile-design-language"><code>mobile-design-language.md</code></a>。</p><h2 id="_1-分层原则" tabindex="-1">1. 分层原则 <a class="header-anchor" href="#_1-分层原则" aria-label="Permalink to &quot;1. 分层原则&quot;">​</a></h2><p>AIO Hub Mobile 是 Tauri v2、Vue 3 和 TypeScript 应用。页面结构与视觉语言由项目自身控制，Varlet 的角色类似桌面端的 Element Plus，只提供可替换的底层控件。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AIO Hub token</span></span>
<span class="line"><span>  -&gt; 原生 Vue 页面和工具业务组件</span></span>
<span class="line"><span>  -&gt; mobile/src/components/base 与 common</span></span>
<span class="line"><span>  -&gt; Varlet 原子组件适配</span></span></code></pre></div><p>主题和组件依赖不得反向由 Varlet 或 Material Design 3 决定。</p><h2 id="_2-页面与组件" tabindex="-1">2. 页面与组件 <a class="header-anchor" href="#_2-页面与组件" aria-label="Permalink to &quot;2. 页面与组件&quot;">​</a></h2><ul><li>页面、导航容器、列表信息架构、弹层骨架、聊天输入区和设置分组优先使用语义明确的原生 Vue 结构与项目 CSS。</li><li>工具内部组件放在 <code>mobile/src/tools/{toolId}/components/</code>；只有出现真实跨工具复用时才沉淀到 <code>mobile/src/components/base/</code> 或 <code>common/</code>。</li><li>Varlet 可用于按钮、输入、选择器、开关、加载态等叶子控件。</li><li>新页面不要直接用 <code>var-app-bar</code>、<code>var-cell</code>、<code>var-card</code>、<code>var-paper</code>、<code>var-popup</code> 或 <code>var-bottom-navigation</code> 搭建主结构。</li><li>维护旧页面时按实际痛点渐进替换，不要求为了形式统一一次性重写可用组件。</li></ul><h2 id="_3-主题与反馈" tabindex="-1">3. 主题与反馈 <a class="header-anchor" href="#_3-主题与反馈" aria-label="Permalink to &quot;3. 主题与反馈&quot;">​</a></h2><ul><li>颜色、边框、圆角、间距、阴影、字体和模糊效果以移动端 AIO Hub token 为准。</li><li>Varlet CSS 变量只能由项目 token 派生，用于适配保留的原子控件。</li><li>业务提示与确认通过 <code>mobile/src/utils/feedback.ts</code> 导出的 <code>customMessage</code> 和 <code>customDialog</code>；不要在业务代码中直接调用 Varlet <code>Snackbar</code> 或 <code>Dialog</code>。</li><li>新增界面需要同时检查明暗主题、安全区、键盘避让、触控目标、长文本和窄屏布局。</li></ul><h2 id="_4-新增工具检查" tabindex="-1">4. 新增工具检查 <a class="header-anchor" href="#_4-新增工具检查" aria-label="Permalink to &quot;4. 新增工具检查&quot;">​</a></h2><ol><li>使用 <code>{toolId}.registry.ts</code> 注册工具、路由和语言包。</li><li>页面级组件放在工具的 <code>views/</code>，业务组件放在 <code>components/</code>。</li><li>优先复用现有主题 token、反馈封装和移动端通用组件。</li><li>对核心逻辑补充 Vitest；Tauri API 使用 mock 只能验证调用契约，不能代替真机或真实 WebView。</li><li>完成类型检查和移动端 Vite 构建后，再按功能范围决定是否需要 Android/iOS 真机验收。</li></ol>`,12)])])}const b=a(t,[["render",s]]);export{m as __pageData,b as default};
